function calculateGraduatedTax(
  taxableMinor: number,
  brackets: Bracket[]
): { taxMinor: number; topMarginalRate: number } {
  if (taxableMinor <= 0) {
    return { taxMinor: 0, topMarginalRate: 0 };
  }

  let taxMinor = 0;
  let previousThresholdMinor = 0;
  let topMarginalRate = 0;

  for (const bracket of brackets) {
    if (taxableMinor > previousThresholdMinor) {
      const taxableInBracket = Math.min(taxableMinor, bracket.upToMinor) - previousThresholdMinor;
      if (taxableInBracket > 0) {
        taxMinor += taxableInBracket * bracket.rate;
        topMarginalRate = bracket.rate;
      }
      previousThresholdMinor = bracket.upToMinor;
    } else {
      break;
    }
  }

  return { taxMinor: Math.round(taxMinor), topMarginalRate };
}

/**
 * Official 2026 New York State Tax Computation Worksheets for Single Filers
 * Authority: NYS Department of Taxation and Finance, Form IT-2105-I (2026) / Tax Law § 601(d)
 *
 * For NYAGI <= $107,650:
 *   Standard graduated tax schedule (3.90% to 10.90%).
 * For NYAGI > $107,650:
 *   Special tax computation / tax table benefit recapture worksheets phase out
 *   the benefit of lower tax brackets:
 *   - Worksheet 7: NYAGI > $107,650 and taxable income <= $215,400.
 *     Phases in flat 5.90% over NYAGI $107,650–$157,650. (Flat 5.90% if NYAGI >= $157,650).
 *   - Worksheet 8: NYAGI > $215,400 and taxable income $215,400–$1,077,550.
 *     Recaptures lower brackets to 6.85% (Base $567 + incremental $2,047 phased in over $215,400–$265,400).
 *   - Worksheet 9: NYAGI > $1,077,550 and taxable income $1,077,550–$5,000,000.
 *     Recaptures to 9.65% (Base $2,614 + incremental $30,172 phased in over $1,077,550–$1,127,550).
 *   - Worksheet 10: NYAGI > $5,000,000 and taxable income $5,000,000–$25,000,000.
 *     Recaptures to 10.30% (Base $32,786 + incremental $32,500 phased in over $5,000,000–$5,050,000).
 *   - Worksheet 11: NYAGI > $25,000,000.
 *     Flat 10.90% on all taxable income.
 */
export function calculateNysTax2026Single(
  nyagiMinor: number,
  nysTaxableMinor: number
): { taxMinor: number; topMarginalRate: number; worksheetApplied?: string } {
  if (nysTaxableMinor <= 0) {
    return { taxMinor: 0, topMarginalRate: 0 };
  }

  // Normal graduated tax for NYAGI <= $107,650
  if (nyagiMinor <= 107_650_00) {
    const base = calculateGraduatedTax(nysTaxableMinor, NYS_BRACKETS_SINGLE_2026);
    return { taxMinor: base.taxMinor, topMarginalRate: base.topMarginalRate };
  }

  // Worksheet 11: NYAGI > $25,000,000 (flat 10.90% on all taxable income)
  // Official 2026 Form IT-2105-I: If NYAGI > $25,000,000, tax = taxable income × 10.9%.
  // Checked BEFORE Worksheet 7/8/9/10 selection. At exactly $25,000,000 NYAGI, do NOT use Worksheet 11.
  if (nyagiMinor > 25_000_000_00) {
    const line2 = Math.round(nysTaxableMinor * 0.1090);
    return { taxMinor: line2, topMarginalRate: 0.1090, worksheetApplied: 'Worksheet 11' };
  }

  // Taxable income <= $215,400 (Worksheet 7)
  if (nysTaxableMinor <= 215_400_00) {
    const line3 = Math.round(nysTaxableMinor * 0.0590);
    if (nyagiMinor >= 157_650_00) {
      // Full recapture of brackets below 5.90% -> flat 5.90% on entire taxable income
      return { taxMinor: line3, topMarginalRate: 0.0590, worksheetApplied: 'Worksheet 7' };
    }
    const line4 = calculateGraduatedTax(nysTaxableMinor, NYS_BRACKETS_SINGLE_2026).taxMinor;
    const line5 = line3 - line4;
    const line6 = nyagiMinor - 107_650_00;
    const line7 = Math.round((line6 / 50_000_00) * 10000) / 10000;
    const line8 = Math.round(line5 * line7);
    const line9 = line4 + line8;
    return { taxMinor: line9, topMarginalRate: 0.0590, worksheetApplied: 'Worksheet 7' };
  }

  // Taxable income > $215,400 and <= $1,077,550 (Worksheet 8)
  if (nysTaxableMinor <= 1_077_550_00) {
    const line3 = calculateGraduatedTax(nysTaxableMinor, NYS_BRACKETS_SINGLE_2026).taxMinor;
    const line4 = 567_00;
    const line5 = 2047_00;
    const line6 = Math.max(0, nyagiMinor - 215_400_00);
    const line7 = Math.min(line6, 50_000_00);
    const line8 = Math.round((line7 / 50_000_00) * 10000) / 10000;
    const line9 = Math.round(line5 * line8);
    const line10 = line3 + line4 + line9;
    return { taxMinor: line10, topMarginalRate: 0.0685, worksheetApplied: 'Worksheet 8' };
  }

  // Taxable income > $1,077,550 and <= $5,000,000 (Worksheet 9)
  if (nysTaxableMinor <= 5_000_000_00) {
    const line3 = calculateGraduatedTax(nysTaxableMinor, NYS_BRACKETS_SINGLE_2026).taxMinor;
    const line4 = 2614_00;
    const line5 = 30172_00;
    const line6 = Math.max(0, nyagiMinor - 1_077_550_00);
    const line7 = Math.min(line6, 50_000_00);
    const line8 = Math.round((line7 / 50_000_00) * 10000) / 10000;
    const line9 = Math.round(line5 * line8);
    const line10 = line3 + line4 + line9;
    return { taxMinor: line10, topMarginalRate: 0.0965, worksheetApplied: 'Worksheet 9' };
  }

  // Taxable income > $5,000,000 and NYAGI <= $25,000,000 (Worksheet 10)
  const line3 = calculateGraduatedTax(nysTaxableMinor, NYS_BRACKETS_SINGLE_2026).taxMinor;
  const line4 = 32786_00;
  const line5 = 32500_00;
  const line6 = Math.max(0, nyagiMinor - 5_000_000_00);
  const line7 = Math.min(line6, 50_000_00);
  const line8 = Math.round((line7 / 50_000_00) * 10000) / 10000;
  const line9 = Math.round(line5 * line8);
  const line10 = line3 + line4 + line9;
  return { taxMinor: line10, topMarginalRate: 0.1030, worksheetApplied: 'Worksheet 10' };
}

export class UsTaxAdapter implements TaxAdapter {
  id = 'us';
  name = 'United States Tax Engine';

  supports(context: TaxContext): boolean {
    return context.countryId === 'US';
  }

  calculate(gross: Money, profile: TaxProfile, context: TaxContext): TaxResult {
    const currency: CurrencyCode = 'USD';
    const grossMinor = gross.amountMinor;

    // Effective-period rule selection
    const requestedYear = profile.taxYear || context.taxYear || 2026;
    const taxYear = requestedYear <= 2024 ? 2024 : requestedYear === 2025 ? 2025 : 2026;

    // Select statutory brackets and parameters
    const federalStdDeductions =
      taxYear === 2024
        ? US_FEDERAL_STANDARD_DEDUCTION_2024
        : taxYear === 2025
        ? US_FEDERAL_STANDARD_DEDUCTION_2025
        : US_FEDERAL_STANDARD_DEDUCTION_2026;
    const federalBracketsMap =
      taxYear === 2024
        ? US_FEDERAL_BRACKETS_2024
        : taxYear === 2025
        ? US_FEDERAL_BRACKETS_2025
        : US_FEDERAL_BRACKETS_2026;
    const socialSecurityCapMinor =
      taxYear === 2024
        ? SOCIAL_SECURITY_CAP_2024_MINOR
        : taxYear === 2025
        ? SOCIAL_SECURITY_CAP_2025_MINOR
        : SOCIAL_SECURITY_CAP_2026_MINOR;

    // Pre-tax deductions (e.g. 401k/HSA/Pension)
    const preTaxDeductionsMinor =
      (profile.pensionContributionMinor || 0) + (profile.healthDeductionMinor || 0);

    const adjustedGrossMinor = Math.max(0, grossMinor - preTaxDeductionsMinor);

    // 1. Federal Standard Deduction & Tax
    const federalStdDeductionMinor = federalStdDeductions[profile.filingStatus];
    const federalTaxableMinor = Math.max(0, adjustedGrossMinor - federalStdDeductionMinor);
    const federalBrackets = federalBracketsMap[profile.filingStatus];
    const { taxMinor: federalTaxMinor, topMarginalRate: federalMarginal } = calculateGraduatedTax(
      federalTaxableMinor,
      federalBrackets
    );

    // 2. FICA: Social Security & Medicare
    const socialSecuritySubjectMinor = Math.min(grossMinor, socialSecurityCapMinor);
    const socialSecurityTaxMinor = Math.round(socialSecuritySubjectMinor * SOCIAL_SECURITY_RATE);

    const standardMedicareTaxMinor = Math.round(grossMinor * MEDICARE_RATE);
    const addlMedicareThresholdMinor = ADDL_MEDICARE_THRESHOLD_MINOR[profile.filingStatus];
    const addlMedicareSubjectMinor = Math.max(0, grossMinor - addlMedicareThresholdMinor);
    const addlMedicareTaxMinor = Math.round(addlMedicareSubjectMinor * ADDL_MEDICARE_RATE);
    const totalMedicareTaxMinor = standardMedicareTaxMinor + addlMedicareTaxMinor;

    const totalFicaMinor = socialSecurityTaxMinor + totalMedicareTaxMinor;

    // 3. State & Local Tax
    let stateTaxMinor = 0;
    let localTaxMinor = 0;
    let stateMarginal = 0;
    let localMarginal = 0;
    const reg = (context.regionId || '').toUpperCase();
    const isNewYorkState =
      reg === 'US-NY' ||
      reg === 'NY' ||
      context.cityId === 'nyc' ||
      context.taxJurisdictionId?.includes('NY');
    const isNycResident =
      context.cityId === 'nyc' ||
      context.taxJurisdictionId === 'US-FED-NY-NYC' ||
      context.taxJurisdictionId === 'tax-us-ny-nyc';

    let nysTaxableMinor = 0;

    if (isNewYorkState) {
      const nysStdDeductionMinor = NYS_STANDARD_DEDUCTION[profile.filingStatus];
      nysTaxableMinor = Math.max(0, adjustedGrossMinor - nysStdDeductionMinor);

      if (taxYear === 2026 && profile.filingStatus === 'single') {
        // Official 2026 NYS Tax Computation Worksheets (Form IT-2105-I / NYS Tax Law § 601(d))
        const stateCalc = calculateNysTax2026Single(adjustedGrossMinor, nysTaxableMinor);
        stateTaxMinor = stateCalc.taxMinor;
        stateMarginal = stateCalc.topMarginalRate;
      } else {
        // Select the correct NYS rate schedule for the tax year (2025 or other filing statuses)
        const nysBrackets = taxYear === 2026 ? NYS_BRACKETS_SINGLE_2026 : NYS_BRACKETS_SINGLE_2025;
        const stateCalc = calculateGraduatedTax(nysTaxableMinor, nysBrackets);
        stateTaxMinor = stateCalc.taxMinor;
        stateMarginal = stateCalc.topMarginalRate;
      }

      if (isNycResident) {
        // NYC Resident tax applies to NY taxable income (same schedule 2024–2026)
        const localCalc = calculateGraduatedTax(nysTaxableMinor, NYC_BRACKETS_SINGLE);
        localTaxMinor = localCalc.taxMinor;
        localMarginal = localCalc.topMarginalRate;
      }
    } else if (reg === 'US-CA' || reg === 'CA') {
      // California Franchise Tax Board
      const caTaxable = Math.max(0, adjustedGrossMinor - 5363_00);
      const caCalc = calculateGraduatedTax(caTaxable, [
        { upToMinor: 10412_00, rate: 0.01 },
        { upToMinor: 24684_00, rate: 0.02 },
        { upToMinor: 38959_00, rate: 0.04 },
        { upToMinor: 54081_00, rate: 0.06 },
        { upToMinor: 68350_00, rate: 0.08 },
        { upToMinor: 349137_00, rate: 0.093 },
        { upToMinor: Infinity, rate: 0.103 },
      ]);
      stateTaxMinor = caCalc.taxMinor;
      stateMarginal = caCalc.topMarginalRate;
    } else if (reg === 'US-IL' || reg === 'IL') {
      // Illinois flat individual income tax rate 4.95%
      const ilTaxable = Math.max(0, adjustedGrossMinor - 2775_00);
      stateTaxMinor = Math.round(ilTaxable * 0.0495);
      stateMarginal = 0.0495;
    } else if (reg === 'US-MA' || reg === 'MA') {
      // Massachusetts flat personal income tax 5.0%
      const maTaxable = Math.max(0, adjustedGrossMinor - 4400_00);
      stateTaxMinor = Math.round(maTaxable * 0.05);
      stateMarginal = 0.05;
    } else if (reg === 'US-DC' || reg === 'DC') {
      // District of Columbia progressive tax
      const dcTaxable = Math.max(0, adjustedGrossMinor - 14600_00);
      const dcCalc = calculateGraduatedTax(dcTaxable, [
        { upToMinor: 10000_00, rate: 0.04 },
        { upToMinor: 40000_00, rate: 0.06 },
        { upToMinor: 60000_00, rate: 0.065 },
        { upToMinor: 250000_00, rate: 0.085 },
        { upToMinor: 500000_00, rate: 0.0925 },
        { upToMinor: Infinity, rate: 0.0975 },
      ]);
      stateTaxMinor = dcCalc.taxMinor;
      stateMarginal = dcCalc.topMarginalRate;
    }
    // Texas (US-TX/TX), Washington (US-WA/WA), and Florida (US-FL/FL) have 0% state personal income tax

    const totalIncomeTaxMinor = federalTaxMinor + stateTaxMinor + localTaxMinor;
    const totalDeductionsAndTaxesMinor = totalIncomeTaxMinor + totalFicaMinor;
    const netIncomeMinor = Math.max(0, grossMinor - totalDeductionsAndTaxesMinor);

    const fedEvidenceId = `us-irs-tax-${taxYear}`;
    const ficaEvidenceId = `us-ssa-fica-${taxYear}`;
    const nysEvidenceId = `us-nys-tax-${taxYear}`;
    const nycEvidenceId = `us-nyc-tax-${taxYear}`;

    const components: TaxComponentBreakdown[] = [
      {
        id: 'us-fed-income-tax',
        name: 'Federal Income Tax',
        authority: 'Internal Revenue Service (IRS)',
        category: 'federal',
        amount: fromMinor(federalTaxMinor, currency),
        effectiveRate: grossMinor > 0 ? federalTaxMinor / grossMinor : 0,
        marginalRate: federalMarginal,
        description: `Taxable Income: $${(federalTaxableMinor / 100).toLocaleString()} (Standard deduction $${(federalStdDeductionMinor / 100).toLocaleString()})`,
        evidenceRefId: fedEvidenceId,
      },
      {
        id: 'us-fica-social-security',
        name: 'Social Security (OASDI)',
        authority: 'Social Security Administration',
        category: 'social_contribution',
        amount: fromMinor(socialSecurityTaxMinor, currency),
        effectiveRate: grossMinor > 0 ? socialSecurityTaxMinor / grossMinor : 0,
        marginalRate: grossMinor < socialSecurityCapMinor ? SOCIAL_SECURITY_RATE : 0,
        description: `6.2% on wages up to $${(socialSecurityCapMinor / 100).toLocaleString()} maximum annual wage base`,
        evidenceRefId: ficaEvidenceId,
      },
      {
        id: 'us-fica-medicare',
        name: 'Medicare & Additional Medicare',
        authority: 'Centers for Medicare & Medicaid / IRS',
        category: 'social_contribution',
        amount: fromMinor(totalMedicareTaxMinor, currency),
        effectiveRate: grossMinor > 0 ? totalMedicareTaxMinor / grossMinor : 0,
        marginalRate: grossMinor > addlMedicareThresholdMinor ? MEDICARE_RATE + ADDL_MEDICARE_RATE : MEDICARE_RATE,
        description: `1.45% uncapped + 0.9% on earnings exceeding $200k`,
        evidenceRefId: ficaEvidenceId,
      },
    ];

    if (stateTaxMinor > 0 || isNewYorkState) {
      components.push({
        id: 'us-state-tax',
        name: isNewYorkState ? 'New York State Personal Income Tax' : 'State Income Tax',
        authority: isNewYorkState ? 'NYS Dept of Taxation and Finance' : 'State Tax Agency',
        category: 'state',
        amount: fromMinor(stateTaxMinor, currency),
        effectiveRate: grossMinor > 0 ? stateTaxMinor / grossMinor : 0,
        marginalRate: stateMarginal,
        description: isNewYorkState
          ? `NYS Standard Deduction $${(NYS_STANDARD_DEDUCTION[profile.filingStatus] / 100).toLocaleString()}`
          : undefined,
        evidenceRefId: isNewYorkState ? nysEvidenceId : fedEvidenceId,
      });
    }

    if (localTaxMinor > 0 || isNycResident) {
      components.push({
        id: 'us-nyc-local-tax',
        name: 'New York City Resident Income Tax',
        authority: 'NYC Department of Finance',
        category: 'local',
        amount: fromMinor(localTaxMinor, currency),
        effectiveRate: grossMinor > 0 ? localTaxMinor / grossMinor : 0,
        marginalRate: localMarginal,
        description: 'NYC Resident Tax Schedule (Admin Code § 11-1701)',
        evidenceRefId: nycEvidenceId,
      });
    }

    const effectiveTaxRate = grossMinor > 0 ? totalDeductionsAndTaxesMinor / grossMinor : 0;
    const combinedMarginalRate =
      federalMarginal +
      stateMarginal +
      localMarginal +
      (grossMinor < socialSecurityCapMinor ? SOCIAL_SECURITY_RATE : 0) +
      MEDICARE_RATE +
      (grossMinor > addlMedicareThresholdMinor ? ADDL_MEDICARE_RATE : 0);

    const taxRuleVersion = `US-FED-NY-NYC-${taxYear}.1`;
    const evidenceSourceIds = [
      fedEvidenceId,
      ficaEvidenceId,
      ...(isNewYorkState ? [nysEvidenceId] : []),
      ...(isNycResident ? [nycEvidenceId] : []),
    ];

    return {
      status: 'CALCULATED',
      grossIncome: gross,
      taxableIncome: fromMinor(federalTaxableMinor, currency),
      deductions: fromMinor(federalStdDeductionMinor, currency),
      federalTax: fromMinor(federalTaxMinor, currency),
      stateTax: fromMinor(stateTaxMinor, currency),
      localTax: fromMinor(localTaxMinor, currency),
      socialContributions: fromMinor(totalFicaMinor, currency),
      totalTax: fromMinor(totalIncomeTaxMinor, currency),
      totalDeductionsAndTaxes: fromMinor(totalDeductionsAndTaxesMinor, currency),
      netIncome: fromMinor(netIncomeMinor, currency),
      monthlyNetIncome: fromMinor(Math.round(netIncomeMinor / 12), currency),
      biweeklyNetIncome: fromMinor(Math.round(netIncomeMinor / 26), currency),
      effectiveTaxRate,
      marginalTaxRate: combinedMarginalRate,
      components,
      taxRuleVersion,
      evidenceSourceIds,
    };
  }
}
